"use strict";
(() => {
  const $ = id => document.getElementById(id);
  const snapshot = window.TENDORA_SNAPSHOT;
  if (!snapshot || !snapshot.world || !snapshot.world.head) {
    $("notice").textContent = "The snapshot is missing. Run ./tendora view, then reopen this page.";
    return;
  }
  const world = snapshot.world, state = world.head.state, next = world.next;
  const text = (id, value) => { $(id).textContent = value; };
  text("day", state.day);
  text("weather", "Next: " + next.weather.toLowerCase());
  text("notice", "Saved " + world.generated_at + " · receipt " + world.head.id +
    ". This page is a snapshot. Refresh it with ./tendora view after changing the world.");
  for (const key of ["water", "food", "soil"]) {
    text(key, state[key]);
    $(key + "-meter").value = state[key];
    $(key + "-meter").low = state[key + "_floor"];
    text(key + "-detail", "Protected floor " + state[key + "_floor"] +
      " · room above it: " + (state[key] - state[key + "_floor"]));
  }
  for (let i = 1; i <= 3; i++) $("bed-" + i).style.opacity = i <= state.beds ? "1" : ".35";
  text("next-action", next.safe ?
    "Next day: tend " + next.irrigated + " beds, harvest " + next.harvest +
      ", return " + next.compost + " food to the soil." :
    "The next day pauses: " + next.stop_reason + ".");
  text("provenance", "Physics 1 · head " + world.head.hash.slice(0, 12));
  const history = world.events.filter(e => e.kind === "genesis" || e.kind === "tick").slice(-37);
  const ns = "http://www.w3.org/2000/svg";
  function svgElement(tag, attrs, content) {
    const node = document.createElementNS(ns, tag);
    for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
    if (content !== undefined) node.textContent = content;
    return node;
  }
  function chart(future) {
    const root = $("history-chart");
    root.replaceChildren();
    const projected = future ? [state, ...future.events.filter(e => e.kind === "tick").map(e => e.state)] : [];
    const past = history.map(e => e.state);
    const first = past.length ? past[0].day : state.day;
    const last = Math.max(first + 1, projected.length ? projected[projected.length - 1].day : state.day);
    const x = day => 36 + 548 * (day - first) / (last - first);
    const y = (value, maximum) => 214 - 186 * value / maximum;
    for (const fraction of [0, .25, .5, .75, 1]) {
      const yy = y(fraction, 1);
      root.append(svgElement("line", {x1:36, y1:yy, x2:584, y2:yy, class:"chart-grid"}));
      root.append(svgElement("text", {x:26, y:yy + 4, "text-anchor":"end", class:"chart-label"}, fraction * 24));
    }
    const days = [...new Set([first, state.day, last])];
    for (const day of days) root.append(svgElement("text",
      {x:x(day), y:240, "text-anchor":"middle", class:"chart-label"}, "day " + day));
    if (future) root.append(svgElement("line", {x1:x(state.day), y1:20, x2:x(state.day), y2:215,
      stroke:"#7c816b", "stroke-dasharray":"2 4"}));
    for (const [key, maximum, color] of [["water",24,"#8bbbbe"],["food",24,"#dfb36c"],["soil",10,"#9ab581"]]) {
      const line = (points, isFuture) => {
        if (!points.length) return;
        const d = points.map((s, i) => (i ? "L" : "M") + x(s.day) + " " + y(s[key], maximum)).join(" ");
        root.append(svgElement("path", {d, stroke:color, class:"chart-line" + (isFuture ? " chart-future" : "")}));
        if (points.length === 1) root.append(svgElement("circle",
          {cx:x(points[0].day),cy:y(points[0][key],maximum),r:3,fill:color}));
      };
      line(past, false); line(projected, true);
    }
  }
  const names = {1:"A gentler hand",2:"Steady care",3:"A larger harvest"};
  const reasons = {1:"Let the soil recover and watch the food reserve.",
    2:"Maintain a balance between harvest and renewal.",
    3:"Explore higher yield within the protected floors."};
  const buttons = [];
  function selectFuture(future, index) {
    buttons.forEach((button, i) => button.setAttribute("aria-pressed", String(i === index)));
    const target = future.end.beds;
    const refusal = future.events.find(e => e.kind === "pause");
    text("future-detail", refusal ?
      "Paused before day " + refusal.body.proposed.day + ": " + refusal.body.stop_reason +
      ". " + future.completed_steps + " safe days precede the pause." :
      "Twelve days can continue. End reserves: water " + future.end.water +
      ", food " + future.end.food + ", soil " + future.end.soil + ".");
    text("command", "./tendora rehearse 12 beds " + target +
      "\n./tendora set beds " + target + " --why '" + reasons[target] +
      "'\n./tendora tend 12\n./tendora view");
    text("copy-status", "");
    chart(future);
  }
  snapshot.futures.forEach((future, index) => {
    const target = future.end.beds;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "future" + (future.outcome === "paused" ? " paused" : "");
    button.setAttribute("aria-pressed", "false");
    for (const [cls, content] of [
      ["eyebrow", target + (target === 1 ? " BED / DAY" : " BEDS / DAY")],
      ["future-name", names[target]],
      ["future-outcome", future.outcome === "paused" ?
        "Paused after " + future.completed_steps + " days" : "12 days within the floors"],
      ["future-tally", "Water " + future.end.water + " · Food " + future.end.food + " · Soil " + future.end.soil]
    ]) {
      const span = document.createElement("span");
      span.className = cls; span.textContent = content; button.append(span);
    }
    button.addEventListener("click", () => selectFuture(future, index));
    buttons.push(button); $("futures").append(button);
  });
  if (snapshot.futures.length) selectFuture(snapshot.futures[1] || snapshot.futures[0], snapshot.futures.length > 1 ? 1 : 0);
  else chart(null);
  $("copy").addEventListener("click", async () => {
    try {
      await window.navigator.clipboard.writeText($("command").textContent);
      text("copy-status", "Copied.");
    } catch (_) { text("copy-status", "Select the commands above and copy them."); }
  });
  const receipts = world.events.slice(-40).reverse();
  text("receipt-count", world.events.length + " receipts · showing the latest " + receipts.length);
  for (const event of receipts) {
    const details = document.createElement("details");
    const summary = document.createElement("summary");
    for (const [cls, content] of [["receipt-id", "#" + event.id + " / day " + event.state.day],
      ["receipt-kind", event.kind], ["receipt-reason", event.reason]]) {
      const span = document.createElement("span"); span.className = cls; span.textContent = content;
      summary.append(span);
    }
    const body = document.createElement("div"); body.className = "receipt-body";
    const stamp = document.createElement("p"); stamp.textContent = event.stamp + " · " + event.hash;
    const data = document.createElement("pre"); data.textContent = JSON.stringify(event.body, null, 2);
    body.append(stamp, data); details.append(summary, body); $("receipts").append(details);
  }
})();

